import{_ as a,o as t,c as d,ag as o}from"./chunks/framework.DyxC4IQh.js";const h=JSON.parse('{"title":"下载","description":"两条发布渠道的版本名规则、APK 下载位置与 SHA-256 校验方法。","frontmatter":{"description":"两条发布渠道的版本名规则、APK 下载位置与 SHA-256 校验方法。"},"headers":[],"relativePath":"download.md","filePath":"download.md","lastUpdated":1793322582000}'),c={name:"download.md"};function r(i,e,s,l,p,n){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to &quot;下载&quot;">​</a></h1><p>VimAct 通过本网站分发 APK。下载入口在本页，APK 文件和校验值放在站点仓库的 Releases 里。</p><p>系统要求：Android 10（API 29）及以上，配一把物理键盘。APK 按 CPU 架构分开出，一个渠道三枚，装哪一枚看机器的架构；拿不准就装 <code>universal</code> 那枚，<code>arm64-v8a</code>、<code>armeabi-v7a</code>、<code>x86</code>、<code>x86_64</code> 四套都在包里。原生库只有一个，是 AndroidX 图形库顺着 Compose 的依赖链带进来的 <code>libandroidx.graphics.path.so</code>，每个架构一份、单份不到 11 KB；本项目自己不含原生代码。</p><h2 id="两个渠道" tabindex="-1">两个渠道 <a class="header-anchor" href="#两个渠道" aria-label="Permalink to &quot;两个渠道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渠道</th><th>版本名形式</th><th>定位</th><th>发布条件</th></tr></thead><tbody><tr><td>正式版</td><td><code>0.1.0</code></td><td>日常可用</td><td>最高级别混淆 + 正式签名 + 真机验证通过</td></tr><tr><td>测试版</td><td><code>0.2.0-beta</code>、<code>0.2.0-beta.2</code></td><td>提前尝新，随时可能坏</td><td>最高级别混淆，不等真机验证结论</td></tr></tbody></table><p>没有第三条渠道。debug 构建是开发机上联调用的，混淆关闭、用调试签名，不具备发布条件，也不会出现在下载页上。</p><p>真机验证只管正式版。正式签名两条渠道都想要，可那把钥匙还没配出来，所以当前这轮测试版由一把试签密钥签发，下一节把这个破例写在明处。装了这轮测试版的人，将来换正式签名那枚会被系统以 <code>INSTALL_FAILED_UPDATE_INCOMPATIBLE</code> 拒掉，要先卸载，无障碍开关和应用里的排除列表跟着没。</p><p>同一个渠道的三枚包共用一个 <code>versionCode</code>，能不能装上只看架构对不对。架构不对，系统报 <code>INSTALL_FAILED_NO_MATCHING_ABIS</code>，界面上通常写着「与设备不兼容」，不会装成半好。版本名一样而 <code>versionCode</code> 更小那种情况是另一回事：装进更小的 <code>versionCode</code> 得先卸载再装。</p><p>版本号按语义化版本走，<code>MAJOR.MINOR.PATCH</code>，当前处于 <code>0.x</code> 阶段。版本名写在 <code>app/build.gradle.kts</code> 的 <code>baseVersionName</code> 里，测试版的 <code>-beta</code> 后缀由 beta 构建类型自动追加；同一轮迭代里出第二个、第三个测试版，后缀带序号 <code>-beta.2</code>、<code>-beta.3</code>，序号取 tag 尾巴上那个数。发下一轮时改 <code>baseVersionName</code> 这一行，并把 <code>versionCode</code> 抬上去，两处都还是手工。文件名格式 <code>vimact-&lt;版本名&gt;-&lt;渠道&gt;-&lt;架构&gt;.apk</code>，架构位取 <code>arm64-v8a</code>、<code>armeabi-v7a</code> 或 <code>universal</code>，装错哪一枚一眼能看出来。</p><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><p>测试版出包了：<code>0.1.0-mvp-beta</code>，2026-10-30 发在站点仓库的 Releases，标记为 pre-release。三枚都是最高级别混淆的产物（R8 full mode、类打平到默认包、方法名激进重载、资源压缩、不保留行号与源文件名，两条渠道共用同一份混淆配置），逐包过完十一条静态体检与验签，同一把试签密钥（证书 SHA-256 开头 <code>6d9cc0f4</code>）签发。正式版还没有构建。</p><table tabindex="0"><thead><tr><th>文件</th><th>给谁</th><th>大小</th><th>SHA-256</th></tr></thead><tbody><tr><td><a href="https://github.com/adam-ikari/vimact-site/releases/download/v0.1.0-mvp-beta/vimact-0.1.0-mvp-beta-arm64-v8a.apk" target="_blank" rel="noreferrer">vimact-0.1.0-mvp-beta-arm64-v8a.apk</a></td><td>近几年的手机和平板，绝大多数机器</td><td>3,403,853 字节</td><td><code>cee2a3e9f7b5a06b4a4df67483e30e9ac71aaad82805cbf40450ffc50884843c</code></td></tr><tr><td><a href="https://github.com/adam-ikari/vimact-site/releases/download/v0.1.0-mvp-beta/vimact-0.1.0-mvp-beta-armeabi-v7a.apk" target="_blank" rel="noreferrer">vimact-0.1.0-mvp-beta-armeabi-v7a.apk</a></td><td>更老的 32 位 ARM 机器</td><td>3,401,011 字节</td><td><code>ac68f942812eba2cd0e5fa9b1700510d76c377d7929d42aea8beacec8de985ee</code></td></tr><tr><td><a href="https://github.com/adam-ikari/vimact-site/releases/download/v0.1.0-mvp-beta/vimact-0.1.0-mvp-beta-universal.apk" target="_blank" rel="noreferrer">vimact-0.1.0-mvp-beta-universal.apk</a></td><td>不确定架构时选这个，四套架构都在包里</td><td>3,453,926 字节</td><td><code>1de629ff18da8573dbffcbf0cebd744434c4f47b4717a565b7b33e83cfbe6dcf</code></td></tr></tbody></table><p>判断架构只有一条硬依据：连上手机跑 <code>adb shell getprop ro.product.cpu.abi</code>，回什么就装什么。不想连 adb 就装通用包，多花 50,073 字节换一次不用判断。</p><p>发布脚本挡在几条硬门槛上，任何一条不合就退出，远端什么都不会动：三枚产物要取齐、版本名要一致且等于 tag、混淆后的静态体检十一条逐包全过、包必须签名且只允许一个签名者、三枚的证书必须是同一把、也不能带 <code>debuggable</code> 标记。正式版另外要写明真机验证已经跑过，并且指纹要就是仓库里登记的那把正式指纹。这一轮测试版跳过的只有最后那半句比对，其余照常执行。</p><p>剩下的一件事在人身上：一把正式签名密钥。装机跑通完整闭环仍然是正式版的前提，这轮测试版没有等它，装出问题请在 Releases 里回话。</p><h2 id="完整性校验" tabindex="-1">完整性校验 <a class="header-anchor" href="#完整性校验" aria-label="Permalink to &quot;完整性校验&quot;">​</a></h2><p>每个 APK 旁边都提供 SHA-256，列在对应 Release 的正文里。下载后核对：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sha256sum vimact-&lt;版本名&gt;-&lt;渠道&gt;-&lt;架构&gt;.apk</span></span></code></pre></div><p>对不上就不要装。</p><h2 id="权限清单" tabindex="-1">权限清单 <a class="header-anchor" href="#权限清单" aria-label="Permalink to &quot;权限清单&quot;">​</a></h2><p>APK 不声明 <code>INTERNET</code>。整份清单上只有一条：<code>com.vimact.DYNAMIC_RECEIVER_NOT_EXPORTED_PERMISSION</code>，AndroidX 合并 manifest 时自动加上的，由本应用自己定义，<code>protectionLevel</code> 是 signature，同签名的应用才请求得到，跟系统敏感权限无关。装机时系统弹出的权限请求仍然是空。</p><p>它能读屏幕和派发点击，全部来自你在系统设置里手动授予的无障碍服务，撤销随时生效。不申请录屏权限，不申请存储权限，不含第三方分析 SDK。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>拿到 APK 后用文件管理器打开安装，允许一次「来自此来源的应用」。装完必须去开无障碍服务，否则一切都不会发生，步骤见<a href="/vimact-site/guide/accessibility.html">启用无障碍服务</a>。</p><h2 id="关于自行构建" tabindex="-1">关于自行构建 <a class="header-anchor" href="#关于自行构建" aria-label="Permalink to &quot;关于自行构建&quot;">​</a></h2><p>源码当前未公开，自行构建复现这条路暂时走不通。开放计划写在首个正式版的发布说明里。</p>',26)])])}const m=a(c,[["render",r]]);export{h as __pageData,m as default};
